import {cpiLevelSource} from './planning-cpi-level-data.js';
export const cpiLevelDefinitions={
  cpiLevel:{title:'Translate the dated CPI comparison and test a separate future scenario',fields:[
    ['baseBudget','Illustrative monthly expense in 2020 CAD',3000,0,20000,100],
    ['futureOne','Hypothetical annual price change in first future year (%)',2,-5,10,.5],
    ['futureTwo','Hypothetical annual price change in second future year (%)',1,-5,10,.5]
  ]}
};
export function cpiBudgetPath(baseBudget){
  const base=cpiLevelSource.rows[0].index;
  return cpiLevelSource.rows.map((row,i)=>({...row,value:baseBudget*row.index/base,change:i?row.index/cpiLevelSource.rows[i-1].index-1:0}));
}
export function cpiFutureBudget(start,first,second){return start*(1+first/100)*(1+second/100);}
export function cpiLevelResult(kind,input){
  if(kind!=='cpiLevel')throw Error('Unknown CPI-level topic.');
  const path=cpiBudgetPath(input.baseBudget),last=path.at(-1),cumulative=last.index/path[0].index-1,futureOne=last.value*(1+input.futureOne/100),futureTwo=cpiFutureBudget(last.value,input.futureOne,input.futureTwo);
  return {metrics:[['Canada all-items annual-average index change, 2020–2025',cumulative,'percent'],['Illustrative monthly expense scaled to 2025 CPI',last.value,'money'],['Separate two-year hypothetical expense endpoint',futureTwo,'money']],note:'Observed source: Statistics Canada Table 18-10-0005-01, Canada all-items CPI, annual averages for 2020–2025, not seasonally adjusted, index reference 2002=100. Released 19 January 2026; CSV snapshot retrieved and validated 25 October 2026. Six observations have one row per year, consistent index units and no missing-value or status flag. Historical percentage changes here are calculated from the displayed one-decimal index values, so rounding may differ from published percentage series. The entered 2020 expense is scaled by the all-items index ratio as a teaching illustration; it is not an observed household budget, a personal inflation estimate or an average Canadian spending amount. The separate future changes are user assumptions beginning after the 2025 annual-average anchor, not official data or a forecast. Annual averages are not December prices, latest monthly readings or a dated schedule of bills. No income, tax, interest or spending-quantity adjustment is calculated.',charts:[
    {id:'cpi-level-history',type:'line',title:'A slower increase can leave the price index at a higher level',unit:'decimal',tableUnit:'CPI index, 2002=100',unitLabel:'Canada all-items annual-average CPI index, 2002=100',xLabel:'Calendar year',xMin:2020,xTicks:[2020,2022,2024,2025].map(year=>({value:year,label:year})),series:[{name:'Observed annual-average index',rows:path.map(r=>({x:r.year,value:r.index}))}],source:cpiLevelSource.url,sourceLabel:'Statistics Canada · Table 18-10-0005-01',evidence:'Official statistics · Canada · 2020–2025',note:'The reference value 100 belongs to the index base year 2002; it is not a dollar amount or an inflation target. This plot uses a zero baseline. Each point is an annual average, with straight segments connecting years rather than displaying the monthly path.'},
    {id:'cpi-level-year-changes',type:'bar',title:'Read the annual change separately from the index level',unit:'percent',unitLabel:'Calculated change from the preceding annual-average CPI (%)',rows:path.slice(1).map(r=>({label:String(r.year),value:r.change})),source:cpiLevelSource.url,sourceLabel:'Statistics Canada · source annual index levels',evidence:'Calculated from official index levels',note:'Each bar equals the current annual-average index divided by the preceding annual average, minus one. All five changes are positive. The pace eases after 2022 while the index keeps rising. These are annual-average comparisons, not December-to-December or latest monthly twelve-month changes.'},
    {id:'cpi-level-budget-bridge',type:'waterfall',title:'Translate the accumulated index change into an illustrative expense',unit:'money',rows:[{label:'Entered monthly expense in 2020',value:input.baseBudget},...path.slice(1).map((r,i)=>({label:'Change to '+r.year+' equivalent',value:r.value-path[i].value}))],totalLabel:'Illustrative monthly expense at 2025 CPI',source:cpiLevelSource.url,sourceLabel:'Statistics Canada · index-ratio inputs',evidence:'Illustrative expense scaled by official CPI',note:'Each step is the difference between two consecutive CPI-scaled monthly expense levels. These changes reconcile one monthly expense equivalent; adding the steps does not total all household bills paid over five years. The assumed expense follows Canada’s all-items CPI exactly, which an actual household’s spending may not do.'},
    {id:'cpi-level-future-path',type:'line',title:'Lower positive inflation and zero inflation preserve earlier price increases',unit:'money',xLabel:'Years after 2025 average anchor',series:[{name:'Selected hypothetical changes',rows:[{x:0,value:last.value},{x:1,value:futureOne},{x:2,value:futureTwo}]},{name:'Zero change in both future years',rows:[{x:0,value:last.value},{x:1,value:last.value},{x:2,value:last.value}],dash:true}],note:'This is a separate two-year scenario, not an extension of the observed source series. A positive change raises the level, zero holds it flat and a negative change lowers it. The future controls replace annual assumptions; they do not alter the historical index or the CPI-scaled 2025 anchor. Lines join annual endpoints, not monthly forecasts.'},
    {id:'cpi-level-future-grid',type:'heatmap',signed:true,compactValues:false,title:'Two annual changes compound rather than simply add',unit:'percent',unitLabel:'Hypothetical two-year cumulative price change (%)',columns:['−2%','0%','2%','5%'],rows:[-2,0,2,5].map(first=>({label:'Year 1: '+first+'%',values:[-2,0,2,5].map(second=>(1+first/100)*(1+second/100)-1)})),note:'Rows select the first future year’s change; columns select the second year’s change. This fixed matrix is independent of the controls and uses no official future estimate. Values are cumulative percentage changes from the starting level, not annualised rates. A 2% rise followed by a 2% fall produces a small net fall, because the two percentages apply to different levels.'}
  ]};
}
